# seconds_to_hms :: 3661
def seconds_to_hms(s):
    """Convert seconds into an H:MM:SS string."""
    h = s // 3600
    m = (s % 3600) // 60
    sec = s % 60
    return "{}:{:02d}:{:02d}".format(h, m, sec)

if __name__ == "__main__":
    print(seconds_to_hms(3661))

